#!/bin/sh
# Print the three most frequent client IP addresses, resolving equal counts
# by the order in which the address first occurs in the log.
set -eu

cd "$(dirname "$0")"

awk '
    NF {
        ip = $1
        if (!(ip in count))
            first[ip] = ++sequence
        ++count[ip]
    }
    END {
        for (ip in count)
            printf "%d\t%d\t%s\n", count[ip], first[ip], ip
    }
' access.log |
    sort -k1,1nr -k2,2n |
    head -n 3 |
    awk -F '\t' '{ print $3 }'
